import Foundation
import simd
import KurvenCore
import KurvenLandscape
import KurvenMath

/// `kurven-cli fixtures <dir>` -- the golden fixtures, written by the code
/// they pin.
///
/// `tests/fixtures` holds two kinds of file. The oracle sets (`expr/` values,
/// `contour/`, `npy/`) are third-party libraries' answers, written by
/// `tests/oracles.py` and regenerated by hand. Everything here is the other
/// kind: kurven's own answers to questions whose specs live in this file,
/// regenerated on every check and compared with the commit. A golden file
/// proves nothing about correctness; it proves that a change to the output was
/// made on purpose, and a regeneration is its own commit with the diff in the
/// message.
///
/// The sets, and what each pins:
///
///     contract/  four tiny bundles that between them use every arm of every
///                sum type in the schema; `kurven-cli contract` and kurven-test
///                round trip their manifests.
///     camera/    world points and their projections under each drawing preset.
///     clip/      the visible runs `HiddenLine.clip` cuts from view-space
///                polylines against a depth buffer.
///     hatch/     every hatching source derived from one grid, one perimeter
///                and two kinds of truncation, and the two derived style numbers.
///     expr/      three landscapes built natively, as bundles, and the specs
///                they were built from.
///
/// Some files in these sets are *inputs*, not answers: the seeded noise in the
/// contract bundles' dumped layers, the camera's point cloud, and the clip
/// fixture's depth buffer and polylines (a CPU rasterization of a 1/Γ
/// occluder). They were written once by numpy and the retired Python pipeline,
/// are never regenerated, and must be present in `<dir>`: this reads them and
/// writes the answers beside them.
///
/// Every file was byte-compared with the Python-written one when the Python
/// pipeline was retired; see that commit for what differed and by how much.
enum GoldenFixtures {
    /// The git sha every golden bundle records. A constant, so regenerating
    /// an unchanged set is a no-op and a diff of one is a diff of its content.
    static let gitSha = "golden"

    static func write(to root: URL) throws {
        try contract(root.appendingPathComponent("contract"))
        try camera(root.appendingPathComponent("camera"))
        try clip(root.appendingPathComponent("clip"))
        try hatch(root.appendingPathComponent("hatch"))
        try landscapes(root.appendingPathComponent("expr"))
    }

    // MARK: shared

    /// The three oblique camera, as the published plates set them. Kept here
    /// rather than read from the catalog, so a change to a drawing is a visible
    /// fixture change.
    static let presets: [(String, ObliqueProjection)] = [
        ("recip", ObliqueProjection(shear: 0.5, xAngle: -55, zAngle: -90, flipX: true, yScale: nil)),
        ("elliptic", ObliqueProjection(shear: 0.51, xAngle: -63, zAngle: -90, flipX: true, yScale: nil)),
        ("zeta", ObliqueProjection(shear: -0.18, xAngle: -79.5, zAngle: -90, flipX: true, yScale: 0.75)),
    ]

    static func input(_ url: URL) throws -> URL {
        guard FileManager.default.fileExists(atPath: url.path) else {
            throw CLIError("\(url.path) is a frozen input and is missing; restore it from git")
        }
        return url
    }

    static func directory(_ url: URL) throws {
        try FileManager.default.createDirectory(at: url, withIntermediateDirectories: true)
    }

    static func save<S>(_ paths: PolylineSet<S>, columns: Int, to dir: URL, stem: String) throws {
        let flat: [Double] = paths.vertices.flatMap { v -> [Double] in
            columns == 2 ? [v.x, v.y] : [v.x, v.y, v.z]
        }
        try NPY.write(flat, shape: [paths.vertices.count, columns],
                      to: dir.appendingPathComponent("\(stem).npy"))
        try NPY.write(paths.offsets, shape: [paths.offsets.count],
                      to: dir.appendingPathComponent("\(stem).idx.npy"))
    }

    static func text(_ s: String, to url: URL) throws {
        try Data(s.utf8).write(to: url)
    }

    // MARK: contract

    /// `x² + y` and `x - y` on a 3x4 grid over [-1, 2] x [0, 1].
    static func tinyGrid(ny: Int = 3, nx: Int = 4) -> (height: [Float], phase: [Float]) {
        let ys = NativeLandscape.linspace(0, 1, ny), xs = NativeLandscape.linspace(-1, 2, nx)
        var height: [Float] = [], phase: [Float] = []
        for y in ys {
            for x in xs {
                height.append(Float(x * x + y))
                phase.append(Float(x - y))
            }
        }
        return (height, phase)
    }

    /// Four tiny bundles that between them use every arm of `Truncation`, `Walls`,
    /// `Region` and `LayerSource`, a phase grid and no phase grid, tiles and no
    /// tiles, a clipped and an unclipped layer, a preset and no presets.
    static func contract(_ dir: URL) throws {
        let (height, phase) = tinyGrid()
        let (ny, nx) = (3, 4)
        let domain = Domain(real: Interval(lo: -1, hi: 2), imag: Interval(lo: 0, hi: 1))
        let heightRef = GridRef(file: "height.npy", shape: (ny: ny, nx: nx), dtype: .float32)
        let phaseRef = GridRef(file: "phase.npy", shape: (ny: ny, nx: nx), dtype: .float32)
        func provenance(_ function: String, _ params: [String: JSONValue] = [:]) -> Provenance {
            Provenance(function: function, example: "fixture", params: params,
                       cpuCount: 1, gitSha: gitSha)
        }
        func bundle(_ name: String, _ manifest: Manifest, phase withPhase: Bool,
                    inputs: [String] = []) throws -> URL {
            let url = dir.appendingPathComponent(name)
            try directory(url)
            for path in inputs { _ = try input(url.appendingPathComponent(path)) }
            try NPY.write(height, shape: [ny, nx], to: url.appendingPathComponent("height.npy"))
            if withPhase {
                try NPY.write(phase, shape: [ny, nx], to: url.appendingPathComponent("phase.npy"))
            }
            try text(manifest.canonicalJSON, to: url.appendingPathComponent("manifest.json"))
            return url
        }
        let recip = presets[0].1
        let perimeter = BoundaryPerimeter(edges: [
            PerimeterEdge(start: P2(-1, 0), end: P2(2, 0), density: 8),
            PerimeterEdge(start: P2(2, 0), end: P2(2, 1), density: 4),
            PerimeterEdge(start: P2(2, 1), end: P2(-1, 1), density: 8),
            PerimeterEdge(start: P2(-1, 1), end: P2(-1, 0), density: 4),
        ])

        // (1) uniform truncation, explicit wall mesh, two tiles, both layer kinds.
        let mesh = try bundle("uniform_mesh.kurven", Manifest(
            domain: domain, height: heightRef, phase: phaseRef, truncation: .uniform(2.5),
            occluder: Occluder(step: 2,
                               tiles: [.identity, Affine2(a: -1, b: 0, tx: 3, c: 0, d: 1, ty: 0)],
                               walls: .mesh(vertices: "occluder/walls.npy",
                                            triangles: "occluder/walls.tri.npy"),
                               region: .full, base: 0),
            layers: [
                LayerSpec(name: "mag", role: .magnitude,
                          source: .file(vertices: "layers/mag.npy", offsets: "layers/mag.idx.npy"),
                          width: 0.4, heightPolicy: .level),
                LayerSpec(name: "hatch", role: .scaffold,
                          source: .file(vertices: "layers/hatch.npy", offsets: "layers/hatch.idx.npy"),
                          width: 0.25, heightPolicy: .surface, color: "#333333", clipped: false),
            ],
            presets: [CameraPreset(name: "recip", projection: recip, depthTolerance: 0.02, buffer: 512)],
            provenance: provenance("tiny", ["res": .int(4)])),
            phase: true,
            inputs: ["layers/mag.npy", "layers/mag.idx.npy",
                     "layers/hatch.npy", "layers/hatch.idx.npy"])
        let occluder = mesh.appendingPathComponent("occluder")
        try directory(occluder)
        try NPY.write([0, 0, 0, 1, 0, 0, 1, 0, 1, 0, 0, 1] as [Double], shape: [4, 3],
                      to: occluder.appendingPathComponent("walls.npy"))
        try NPY.write([0, 1, 2, 0, 2, 3], shape: [2, 3],
                      to: occluder.appendingPathComponent("walls.tri.npy"))

        // (2) real-band truncations, walls described as a perimeter, no phase, no
        //     tiles beyond the identity, several presets; a described layer
        //     beside a dumped one, and the whole Restriction vocabulary.
        _ = try bundle("bands_perimeter.kurven", Manifest(
            domain: domain, height: heightRef, phase: nil,
            truncation: .realBands([RealBand(below: -3.5, height: 8), RealBand(below: -2.5, height: 6),
                              RealBand(below: -1.5, height: 4)], beyond: 3),
            occluder: Occluder(step: 1, tiles: [.identity],
                               walls: .perimeter(perimeter, base: 0),
                               region: .inside(perimeter), base: 0),
            layers: [
                LayerSpec(name: "ang", role: .phase,
                          source: .file(vertices: "layers/ang.npy", offsets: "layers/ang.idx.npy"),
                          width: 0.15, heightPolicy: .magnitude),
                LayerSpec(name: "mag_derived", role: .magnitude,
                          source: .contour(field: .magnitude, levels: [0.5, 1.0, 1.5],
                                           restriction: .intersection([.footprint, .belowTruncation,
                                                         .band(axis: .imag, lo: -1, hi: 1)]),
                                           tiled: false),
                          width: 0.3, heightPolicy: .level),
                LayerSpec(name: "all_levels", role: .magnitude,
                          source: .contour(field: .phase, levels: [0.25], restriction: .all, tiled: true),
                          width: 0.2, heightPolicy: .surface),
            ],
            presets: presets.map { CameraPreset(name: $0.0, projection: $0.1, depthTolerance: 0.01, buffer: 1024) },
            provenance: provenance("tiny_bands")),
            phase: false, inputs: ["layers/ang.npy", "layers/ang.idx.npy"])

        // (3) a landscape's own shape: every layer described, and the four
        //     hatching kinds alongside a contour family.
        _ = try bundle("landscape.kurven", Manifest(
            domain: domain, height: heightRef, phase: phaseRef, truncation: .uniform(1.75),
            occluder: Occluder(step: 1, tiles: [.identity],
                               walls: .perimeter(perimeter, base: 0), region: .full, base: 0),
            layers: [
                LayerSpec(name: "mag_major", role: .magnitude,
                          source: .contour(field: .magnitude, levels: [0.5, 1.0, 1.5],
                                           restriction: .belowTruncation, tiled: false),
                          width: 0.4, heightPolicy: .level),
                LayerSpec(name: "truncation_edge", role: .scaffold, source: .truncationEdge(tiled: false),
                          width: 0.4, heightPolicy: .level),
                LayerSpec(name: "plateau_hatch", role: .scaffold,
                          source: .plateauHatching(axis: .real, spacing: 0.25, tiled: false),
                          width: 0.2, heightPolicy: .level),
                LayerSpec(name: "plateau_hatch_tiled", role: .scaffold,
                          source: .plateauHatching(axis: .imag, spacing: 0.4, tiled: true),
                          width: 0.2, heightPolicy: .level),
                LayerSpec(name: "wall_edges", role: .scaffold,
                          source: .wallEdges(edges: [0, 1, 2, 3], step: 0.1, base: 0),
                          width: 0.3, heightPolicy: .surface),
                LayerSpec(name: "wall_hatch", role: .scaffold,
                          source: .wallHatching(edges: [0, 2], spacing: 0.3, step: 0.1, trim: true,
                                             base: 0.01, topOffset: -0.02),
                          width: 0.25, heightPolicy: .surface),
                LayerSpec(name: "folds", role: .outline, source: .foldCurves,
                          width: 0.4, heightPolicy: .surface),
            ],
            presets: [CameraPreset(name: "oblique", projection: recip, depthTolerance: 0.02, buffer: 4000)],
            provenance: provenance("1/gamma(z)", ["expression": .string("1/gamma(z)"),
                                                  "resolution": .int(4)])),
            phase: true)

        // (4) the empty case: no truncations, no walls, no layers, no presets.
        _ = try bundle("empty.kurven", Manifest(
            domain: domain, height: heightRef, phase: nil, truncation: .none,
            occluder: Occluder(step: 1, tiles: [.identity], walls: .none, region: .full, base: 0),
            layers: [], presets: [], provenance: provenance("tiny_empty")),
            phase: false)
    }

    // MARK: camera

    /// World points (x = real, y = imag, z) and where each oblique camera puts
    /// them. The points are a frozen input; the projections are `Camera.oblique`.
    static func camera(_ dir: URL) throws {
        try directory(dir)
        for (name, projection) in presets {
            let world = try NPY.read(contentsOf: input(
                dir.appendingPathComponent("\(name).points.npy"))).rows3()
            let camera = Camera.oblique(projection)
            let projected = world.flatMap { w -> [Double] in
                let v = camera.view(P3<WorldSpace>(w)).v
                return [v.x, v.y, v.z]
            }
            try NPY.write(projected, shape: [world.count, 3],
                          to: dir.appendingPathComponent("\(name).projected.npy"))
            try text(JSONValue.object(["name": .string(name), "projection": projection.json]).canonical + "\n",
                     to: dir.appendingPathComponent("\(name).json"))
        }
    }

    // MARK: clip

    /// The visible runs of sixty straight probes across 1/Γ's drawing, against
    /// a 320² depth buffer of its occluder. The buffer, the probes and the
    /// frame in `meta.json` are frozen inputs; the runs, and their count in
    /// `meta.json`, are `HiddenLine.clip`'s.
    static func clip(_ dir: URL) throws {
        let metaURL = try input(dir.appendingPathComponent("meta.json"))
        var meta = try JSONValue.parse(Data(contentsOf: metaURL)).object("clip meta")
        let axis0 = try meta.doubles("axis0", "clip meta")
        let axis1 = try meta.doubles("axis1", "clip meta")
        let shape = try meta.ints("shape", "clip meta")
        let frame = DepthFrame(axis0: Interval(lo: axis0[0], hi: axis0[1]),
                               axis1: Interval(lo: axis1[0], hi: axis1[1]),
                               rows: shape[0], cols: shape[1],
                               nudge: try meta.double("nudge", "clip meta"))
        let depth = DepthImage(frame: frame, values: try NPY.read(contentsOf: input(
            dir.appendingPathComponent("depth.npy"))).floats())
        let view = try NPY.read(contentsOf: input(dir.appendingPathComponent("view.npy"))).rows3()
            .map { P3<ViewSpace>($0) }
        let offsets = try NPY.read(contentsOf: input(
            dir.appendingPathComponent("view.idx.npy"))).ints()
        let visible = HiddenLine.clip(PolylineSet(vertices: view, offsets: offsets),
                                      against: depth, depthTolerance: try meta.double("depthTolerance", "clip meta"))
        try save(visible, columns: 2, to: dir, stem: "expected")
        meta["segments"] = .int(visible.count)
        try text(JSONValue.object(meta).pretty() + "\n", to: metaURL)
    }

    // MARK: hatch

    /// The hatching fixture's landscape: a grid small enough to read and
    /// awkward enough to matter. One pole sits just inside the back edge, so a
    /// wall top edge runs into the truncation and the two truncations disagree about
    /// where it stops; the other is interior, so there is a plateau with a truncation edge
    /// all the way round. Both are off the sample grid, because a pole *on*
    /// a sample is an infinity in the grid and this fixture is about hatching,
    /// not about sanitizing.
    static let hatchDomain = Domain(real: Interval(lo: -2, hi: 2.5), imag: Interval(lo: -1, hi: 1.5))
    static let hatchShape = (nx: 37, ny: 23)            // deliberately not square

    /// Every hatching source, derived from one float32 grid. Heights come
    /// from the grid, not from f: the fixture pins the derivation, not the
    /// refiner.
    static func hatch(_ dir: URL) throws {
        try directory(dir)
        let (nx, ny) = hatchShape
        let f = try KurvenMath.Expression.compile("1/((z - 1.05 - 1.44i)(z + 0.7 - 0.3i))")
        let xs = NativeLandscape.linspace(hatchDomain.real.lo, hatchDomain.real.hi, nx)
        let ys = NativeLandscape.linspace(hatchDomain.imag.lo, hatchDomain.imag.hi, ny)
        let values = ys.flatMap { y in xs.map { x in Float(f(Complex(x, y)).magnitude) } }
        try NPY.write(values, shape: [ny, nx], to: dir.appendingPathComponent("height.npy"))
        let grid = Grid2D(width: nx, height: ny, domain: hatchDomain, values: values)

        let (r, i) = (hatchDomain.real, hatchDomain.imag)
        let perimeter = BoundaryPerimeter(edges: [
            PerimeterEdge(start: P2(r.lo, i.lo), end: P2(r.hi, i.lo), density: 19),
            PerimeterEdge(start: P2(r.hi, i.lo), end: P2(r.hi, i.hi), density: 11),
            PerimeterEdge(start: P2(r.hi, i.hi), end: P2(r.lo, i.hi), density: 19),
            PerimeterEdge(start: P2(r.lo, i.hi), end: P2(r.lo, i.lo), density: 11),
        ])
        let truncation: [(String, Truncation)] = [
            ("uniform", .uniform(2)),
            // A staircase whose boundary falls between the two poles, so a truncation
            // stroke has to stop at the band edge and start again at another
            // height.
            ("bands", .realBands([RealBand(below: -1, height: 1.2), RealBand(below: 0.4, height: 2.5)],
                                 beyond: 1.6)),
        ]
        let sources: [(String, LayerSource)] = [
            ("wall_hatch", .wallHatching(edges: [0, 1, 2, 3], spacing: 0.35, step: 0.5, trim: true,
                                      base: 0, topOffset: 0)),
            ("wall_hatch_untrimmed", .wallHatching(edges: [0, 2], spacing: 0.6, step: 0.25,
                                                trim: false, base: 0.1, topOffset: -0.05)),
            ("wall_edges", .wallEdges(edges: [0, 1, 2, 3], step: 0.4, base: 0)),
            ("plateau_hatch_real", .plateauHatching(axis: .real, spacing: 0.25, tiled: false)),
            ("plateau_hatch_imag", .plateauHatching(axis: .imag, spacing: 0.3, tiled: false)),
            ("truncation_edge", .truncationEdge(tiled: false)),
        ]

        var cases: [JSONValue] = []
        for (truncationName, truncationHeight) in truncation {
            let surface = Surface(height: grid, phase: nil, truncation: truncationHeight)
            let context = Surface.HatchContext(perimeter: perimeter)
            for (sourceName, source) in sources {
                guard let paths = surface.hatch(source, in: context) else {
                    throw CLIError("\(sourceName) is not a hatching")
                }
                let stem = "\(truncationName)_\(sourceName)"
                try save(paths, columns: 3, to: dir, stem: stem)
                cases.append(.object([
                    "name": .string(stem), "truncation": .string(truncationName), "source": source.json,
                    "vertices": .string("\(stem).npy"), "offsets": .string("\(stem).idx.npy"),
                    "paths": .int(paths.count)]))
            }
        }

        // The two derived numbers a consumer computes for itself, because a
        // truncation it moves has to bring the contour levels with it.
        let style: JSONValue = .object([
            "nice": .array([0.037, 0.12, 0.5, 1.0, 1.4, 2.3, 4.9, 6.0, 7.5, 23.0, 180.0].map { x in
                .object(["x": .double(x), "up": .double(LandscapeStyle.nice(x)),
                         "down": .double(LandscapeStyle.nice(x, down: true))])
            }),
            "levels": .array([1.0, 2.0, 4.0, 5.0, 6.0, 10.0, 12.5, 37.0].map { c in
                let (major, minor) = LandscapeStyle.magnitudeLevels(upTo: c)
                return .object(["ceiling": .double(c),
                                "major": .array(major.map(JSONValue.double)),
                                "minor": .array(minor.map(JSONValue.double))])
            }),
        ])
        let index: JSONValue = .object([
            "domain": hatchDomain.json,
            "shape": .object(["ny": .int(ny), "nx": .int(nx)]),
            "perimeter": perimeter.json,
            "truncation": .object(Dictionary(uniqueKeysWithValues: truncation.map { ($0.0, $0.1.json) })),
            "cases": .array(cases),
            "style": style,
        ])
        try text(index.pretty() + "\n", to: dir.appendingPathComponent("index.json"))
    }

    // MARK: landscapes

    /// Three landscapes built natively with every layer a description. One
    /// leaves the truncation to the rule, one says where to cut and how densely
    /// to hatch, and one is typed rather than chosen from the catalog.
    static func landscapes(_ dir: URL) throws {
        try directory(dir)
        let catalog = Catalog.native
        guard let gamma = catalog.preset("gamma"), let cubic = catalog.preset("cubic"),
              let sin = catalog.preset("sin") else {
            throw CLIError("the catalog has lost gamma, cubic or sin")
        }
        var spaced = LandscapeRequest(preset: cubic, resolution: 64)
        spaced.spacing = 0.4
        let specs: [(String, LandscapeRequest)] = [
            ("landscape_gamma", LandscapeRequest(preset: gamma, resolution: 90)),
            ("landscape_cubic", spaced),
            ("landscape_typed", LandscapeRequest(expression: "sin(z)/z", domain: sin.domain,
                                                 resolution: 48)),
        ]
        var entries: [JSONValue] = []
        for (stem, spec) in specs {
            let bundle = try NativeLandscape.build(spec, gitSha: gitSha, refine: false)
            let url = dir.appendingPathComponent("\(stem).kurven")
            try bundle.write(to: url)
            // A spec spells out what it leaves to the rules, as null.
            var json = try spec.json.object("spec")
            for key in ["truncation", "spacing", "layers"] where json[key] == nil { json[key] = .null }
            entries.append(.object(["bundle": .string("\(stem).kurven"), "spec": .object(json),
                                    "layers": .int(bundle.manifest.layers.count)]))
        }
        try text(JSONValue.object(["landscapes": .array(entries)]).pretty(ascii: false) + "\n",
                 to: dir.appendingPathComponent("landscapes.json"))
    }
}

func fixturesCommand(_ args: Args) throws {
    guard let dir = args.positional.dropFirst().first else {
        throw CLIError("which directory? (tests/fixtures)")
    }
    let clock = ContinuousClock()
    let elapsed = try clock.measure { try GoldenFixtures.write(to: URL(fileURLWithPath: dir)) }
    print("wrote the golden sets under \(dir) in \(elapsed): contract, camera, clip, hatch, "
          + "expr/landscape_*")
}
